<div class="row g-3 mt-1">
  <div class="col-md-3"><label class="field-label" for="search-year">Enactment Year</label><input id="search-year" name="year" type="number" min="1800" max="9999" class="form-control" placeholder="Any year" value="<?= htmlspecialchars($yearFilter) ?>"></div>
  <div class="col-md-3"><label class="field-label" for="search-committee">Committee</label><select id="search-committee" name="committee_id" class="form-select"><option value="0">All committees</option><?php foreach ($searchCommittees as $committee): ?><option value="<?= (int)$committee['id'] ?>" <?= $committeeFilter === (int)$committee['id'] ? 'selected' : '' ?>><?= htmlspecialchars($committee['name']) ?></option><?php endforeach; ?></select></div>
  <div class="col-md-3"><label class="field-label" for="search-office">Originating Office</label><select id="search-office" name="office" class="form-select"><option value="">All offices</option><?php foreach ($searchOffices as $office): ?><option <?= $officeFilter === $office ? 'selected' : '' ?> value="<?= htmlspecialchars($office) ?>"><?= htmlspecialchars($office) ?></option><?php endforeach; ?></select></div>
  <div class="col-md-3"><label class="field-label" for="search-classification">Classification</label><select id="search-classification" name="classification" class="form-select"><option value="">All classifications</option><?php foreach (['PUBLIC','INTERNAL','RESTRICTED','CONFIDENTIAL'] as $classification): ?><option <?= $classificationFilter === $classification ? 'selected' : '' ?>><?= $classification ?></option><?php endforeach; ?></select></div>
</div>
